rows = []
for x in I:
    a = x['anchor']; t = x['target']
    if t in DOC and a:
        n = DOC[t].count(a); x['anchor_count'] = n; x['line'] = line_of(DOC[t], a)
    else:
        x['anchor_count'] = ''; x['line'] = ''
    x['lines2'] = []
    for (d2, a2) in x.get('anchors2', []):
        n2 = DOC[d2].count(a2); x['lines2'].append((d2, line_of(DOC[d2], a2), n2, a2))
    rows.append(x)
# transactions: lines touched by >1 prose item
byline = collections.defaultdict(list)
for x in rows:
    if x['line']: byline[(x['target'], x['line'])].append(x['id'])
    for (d2, l2, n2, a2) in x['lines2']:
        if l2: byline[(d2, l2)].append(x['id'])
trans = {k: v for k, v in byline.items() if len(v) > 1}
for x in rows:
    x['transaction'] = ';'.join(sorted(set(sum([v for k, v in trans.items() if x['id'] in v], [])) - {x['id']}))
for x in rows: x['anchors2_lines'] = ';'.join(f'{d}:{l}({n})' for d,l,n,a in x['lines2'])
keys = ['id','level','target','line','anchor','anchor_count','anchors2_lines','transaction','findings','decision','depends','instruction','value_new','source']
with open('s8work/ledger_S8.csv','w',newline='',encoding='utf-8') as f:
    w = csv.DictWriter(f, fieldnames=keys); w.writeheader(); [w.writerow({k: x.get(k,'') for k in keys}) for x in rows]
bad = [x['id'] for x in rows if x['target'] in DOC and x['anchor'] and x['anchor_count'] != 1] + [x['id']+':'+a2 for x in rows for (d2,l2,n2,a2) in x['lines2'] if n2 != 1]
print('items', len(rows), 'prose anchors', sum(1 for x in rows if x['target'] in DOC and x['anchor']), 'bad anchors', bad)
